  ('ayushman', 'Ayushman Bharat – PM Jan Arogya Yojana (PM-JAY)', 'Health', '["health","hospital","insurance","medical","treatment","senior citizen"]'::jsonb, 'Health cover of ₹5 lakh/year per family for secondary & tertiary hospitalization. Since 2024, ALL senior citizens aged 70+ are covered free, regardless of income — as a separate top-up on top of any existing family cover.', 'Cashless treatment up to ₹5,00,000 per family per year at empanelled hospitals. 70+ citizens get an additional personal ₹5,00,000 top-up, irrespective of income.', '["Aadhaar card","Ration card / family ID","Income certificate (if applicable, not needed for 70+)"]'::jsonb, 'https://pmjay.gov.in', '{"minAge":0,"maxAge":null,"maxIncome":null,"gender":"any","occupation":["any"],"disability":false,"category":"any","sector":"any"}'::jsonb),
