  ('pmay-u', 'Pradhan Mantri Awas Yojana – Urban 2.0 (PMAY-U 2.0)', 'Housing', '["housing","home","house","pucca","shelter","urban","city","home loan"]'::jsonb, 'Interest subsidy on home loans for urban EWS/LIG/MIG families to buy, build, or rent affordable housing (2024–2029 scheme).', '4% interest subsidy, up to ₹1.8 lakh total, on the first ₹8 lakh of a home loan (loan up to ₹25 lakh, property value up to ₹35 lakh).', '["Aadhaar card","Income proof","Bank loan sanction letter","Property documents"]'::jsonb, 'https://pmaymis.gov.in', '{"minAge":18,"maxAge":null,"maxIncome":900000,"gender":"any","occupation":["any"],"disability":false,"category":"any","sector":"urban"}'::jsonb),
