-- Nagrik Sahayak: schemes table schema + seed data
-- Run this in Supabase Dashboard -> SQL Editor -> New query -> Run

drop table if exists schemes;

create table schemes (
  id text primary key,
  name text not null,
  category text,
  tags jsonb,
  description text,
  benefits text,
  documents jsonb,
  link text,
  criteria jsonb
);

